// @FIGURE_CODE_BEGIN
// ── element spec ─────────────────────────────────────────────────────────────
// origin dot          → SphereGeometry(0.13)                                  black
// X / Y / Z axis      → CylinderGeometry(0.04) shaft + ConeGeometry head      black
// yaw/pitch/roll arc  → TorusGeometry(R,0.07, arc 4.2rad) + ConeGeometry head red #E81414
// image plane         → PlaneGeometry(2.8,3.2) MeshBasicMaterial DoubleSide   #DEE8E4
// plane border        → 4 × BoxGeometry bars (0.08 thick)                     black
// green x / y axes    → CylinderGeometry(0.045) + ConeGeometry                #00CC22
// p and P             → SphereGeometry(0.12) cyan + BackSide black outline    #4FC8EC
// drop line p→x axis  → CylinderGeometry(0.026) segment                       grey #8A8A8A
// P footprint poly    → 2 × CylinderGeometry(0.03) segments                   grey #A8A8A8
// ray O→P             → Line, LineDashedMaterial                              #B9B9B9
// ─────────────────────────────────────────────────────────────────────────────

const BLACK = 0x000000, RED = 0xE81414, GREEN = 0x00CC22,
      CYAN = 0x4FC8EC, GREYD = 0x8A8A8A, GREYM = 0xA8A8A8, GREYL = 0xB9B9B9, FILL = 0xDEE8E4;
const SERIF = (t) => `<span style="font-family:Georgia,'Times New Roman',serif">${t}</span>`;
const V3 = (x, y, z) => new THREE.Vector3(x, y, z);

/* ── primitive builders ─────────────────────────────────────────────────── */
function shaftMesh(from, to, r, mat) {
  const dir = new THREE.Vector3().subVectors(to, from);
  const len = Math.max(dir.length(), 1e-5);
  const m = new THREE.Mesh(new THREE.CylinderGeometry(r, r, len, 16), mat);
  m.position.copy(from).addScaledVector(dir, 0.5);
  m.quaternion.setFromUnitVectors(V3(0, 1, 0), dir.clone().normalize());
  return m;
}
function makeArrow(from, to, opt = {}) {
  const r = opt.r ?? 0.04, head = opt.head ?? 0.34, headR = opt.headR ?? 0.135;
  const mat = new THREE.MeshBasicMaterial({ color: opt.color ?? BLACK, transparent: true });
  const g = new THREE.Group();
  const dir = new THREE.Vector3().subVectors(to, from);
  const n = dir.clone().normalize();
  const base = to.clone().addScaledVector(n, -head);
  g.add(shaftMesh(from, base, r, mat));
  const cone = new THREE.Mesh(new THREE.ConeGeometry(headR, head, 20), mat);
  cone.position.copy(base).addScaledVector(n, head / 2);
  cone.quaternion.setFromUnitVectors(V3(0, 1, 0), n);
  g.add(cone);
  g.userData.mat = mat;
  return g;
}
function makeArc(radius, thetaStart, thetaLength, color) {
  const mat = new THREE.MeshBasicMaterial({ color, transparent: true });
  const g = new THREE.Group();
  const tube = 0.07;
  const t = new THREE.Mesh(new THREE.TorusGeometry(radius, tube, 12, 80, thetaLength), mat);
  t.rotation.z = thetaStart;
  g.add(t);
  const a = thetaStart + thetaLength;
  const end = V3(radius * Math.cos(a), radius * Math.sin(a), 0);
  const tan = V3(-Math.sin(a), Math.cos(a), 0);
  const cone = new THREE.Mesh(new THREE.ConeGeometry(tube * 2.6, tube * 7.0, 18), mat);
  cone.position.copy(end).addScaledVector(tan, tube * 3.0);
  cone.quaternion.setFromUnitVectors(V3(0, 1, 0), tan);
  g.add(cone);
  g.userData.mat = mat;
  return g;
}
function makeDisc(radius, color) {
  const g = new THREE.Group();
  g.add(new THREE.Mesh(new THREE.SphereGeometry(radius * 1.3, 20, 14),
    new THREE.MeshBasicMaterial({ color: BLACK, side: THREE.BackSide })));
  const core = new THREE.Mesh(new THREE.SphereGeometry(radius, 20, 14),
    new THREE.MeshBasicMaterial({ color, transparent: true }));
  g.add(core);
  g.userData.core = core;
  return g;
}
function segMesh(r, color) {
  return new THREE.Mesh(new THREE.CylinderGeometry(r, r, 1, 10),
    new THREE.MeshBasicMaterial({ color }));
}
const _sd = new THREE.Vector3();
function setSeg(m, a, b) {
  _sd.subVectors(b, a);
  const len = _sd.length();
  if (len < 1e-4) { m.visible = false; return; }
  m.visible = true;
  m.position.copy(a).addScaledVector(_sd, 0.5);
  m.quaternion.setFromUnitVectors(V3(0, 1, 0), _sd.clone().normalize());
  m.scale.set(1, len, 1);
}
function makeLine(points, color, opts = {}) {
  const geo = new THREE.BufferGeometry().setFromPoints(points);
  const mat = opts.dashed
    ? new THREE.LineDashedMaterial({ color, dashSize: 0.14, gapSize: 0.11 })
    : new THREE.LineBasicMaterial({ color });
  const l = new THREE.Line(geo, mat);
  if (opts.dashed) l.computeLineDistances();
  return l;
}

/* ── world axes (Y up, Z forward-right, X the receding diagonal) ────────── */
const F = 3.0;                        // focal distance (image plane at z = F)
const LY = 3.2, LX = 3.6, LZ = 6.6;   // axis lengths
const P_WORLD = V3(0.5, 1.75, 6.3);   // fixed world point P

const axY = makeArrow(V3(0, 0, 0), V3(0, LY, 0));
const axX = makeArrow(V3(0, 0, 0), V3(LX, 0, 0));
const axZ = makeArrow(V3(0, 0, 0), V3(0, 0, LZ));
scene.add(axY, axX, axZ);

const originDot = new THREE.Mesh(new THREE.SphereGeometry(0.135, 22, 16),
  new THREE.MeshBasicMaterial({ color: BLACK }));
scene.add(originDot);

/* ── rotation arcs ──────────────────────────────────────────────────────── */
const arcYaw = makeArc(0.55, -1.31, 4.2, RED);      // encircles +Y near the top
arcYaw.rotation.x = -Math.PI / 2;
arcYaw.position.set(0, 2.4, 0);

const arcPitch = makeArc(0.50, -2.62, 4.2, RED);    // wraps the X axis at ~60 %
arcPitch.rotation.y = Math.PI / 2;
arcPitch.position.set(2.1, 0, 0);

const arcRoll = makeArc(0.55, -2.62, 4.2, RED);     // wraps the Z axis, far right
arcRoll.position.set(0, 0, 4.6);
scene.add(arcYaw, arcPitch, arcRoll);

/* ── camera frame group (image plane + local axes + p) ──────────────────── */
const camGroup = new THREE.Group();
scene.add(camGroup);

const PW = 2.8, PH = 3.2, PCY = -0.15;   // plane width (along X) / height (along Y) / centre
const planeMat = new THREE.MeshBasicMaterial({
  color: FILL, side: THREE.DoubleSide, transparent: true, opacity: 0.88, depthWrite: false
});
const planeMesh = new THREE.Mesh(new THREE.PlaneGeometry(PW, PH), planeMat);
planeMesh.position.set(0, PCY, F);
planeMesh.renderOrder = -2;
camGroup.add(planeMesh);

const borderMat = new THREE.MeshBasicMaterial({ color: BLACK });
const bt = 0.08;
[PH / 2, -PH / 2].forEach((by) => {
  const bar = new THREE.Mesh(new THREE.BoxGeometry(PW + bt, bt, 0.025), borderMat);
  bar.position.set(0, by + PCY, F);
  camGroup.add(bar);
});
[PW / 2, -PW / 2].forEach((bx) => {
  const bar = new THREE.Mesh(new THREE.BoxGeometry(bt, PH + bt, 0.025), borderMat);
  bar.position.set(bx, PCY, F);
  camGroup.add(bar);
});

// local green image axes, crossing at the principal point (0,0,F) on the optical axis
const gy = makeArrow(V3(0, -1.55, F + 0.05), V3(0, 1.28, F + 0.05),
  { color: GREEN, r: 0.045, head: 0.32, headR: 0.14 });
const gx = makeArrow(V3(-1.26, 0, F + 0.05), V3(1.26, 0, F + 0.05),
  { color: GREEN, r: 0.045, head: 0.32, headR: 0.14 });
camGroup.add(gy, gx);

// image point p (recomputed every frame) + its drop line onto the local x axis
const pDisc = makeDisc(0.12, CYAN);
camGroup.add(pDisc);
const dropSeg = segMesh(0.026, GREYD);
camGroup.add(dropSeg);

/* ── world point P, its footprint, and the projection ray ───────────────── */
const PDisc = makeDisc(0.12, CYAN);
PDisc.position.copy(P_WORLD);
scene.add(PDisc);

// true 3D footprint: straight down from P to the XZ plane, then back along −X to the Z axis
const fpA = segMesh(0.03, GREYM), fpB = segMesh(0.03, GREYM);
setSeg(fpA, V3(P_WORLD.x, P_WORLD.y - 0.16, P_WORLD.z), V3(P_WORLD.x, 0, P_WORLD.z));
setSeg(fpB, V3(P_WORLD.x, 0, P_WORLD.z), V3(0, 0, P_WORLD.z));
scene.add(fpA, fpB);

const rayLine = makeLine([V3(0, 0, 0), P_WORLD], GREYL, { dashed: true });
scene.add(rayLine);

/* ── camera framing (after all geometry) ────────────────────────────────── */
// Pose chosen to reproduce the source composition: Y exactly vertical, Z running
// almost horizontally to the right (≈8° slope), X the receding diagonal at ≈51°.
setCameraView({ projection: 'orthographic', azimuthDeg: 161, elevationDeg: 25.5, heightFraction: 0.78 });

/* ── labels ─────────────────────────────────────────────────────────────── */
const AX = { fontSize: '23px' };
addLabel(SERIF('Y'), V3(0, LY, 0), { ...AX, offset: [-4, -26] });
addLabel(SERIF('X'), V3(LX, 0, 0), { ...AX, offset: [30, -2] });
addLabel(SERIF('Z'), V3(0, 0, LZ), { ...AX, offset: [10, 30] });
addLabel(SERIF('(0,0,0)'), V3(0, 0, 0), { fontSize: '19px', offset: [-54, 32] });

addLabel(SERIF('Yaw'), V3(0, 2.4, 0), { fontSize: '21px', offset: [-82, -24] });
addLabel(SERIF('&theta;<sub>Y</sub>'), V3(0, 2.4, 0), { fontSize: '21px', offset: [-40, 34] });
addLabel(SERIF('Pitch'), V3(2.1, 0, 0), { fontSize: '21px', offset: [14, -76] });
addLabel(SERIF('&theta;<sub>X</sub>'), V3(2.1, 0, 0), { fontSize: '21px', offset: [-66, -10] });
addLabel(SERIF('&theta;<sub>Z</sub>'), V3(0, 0, 4.6), { fontSize: '21px', offset: [-36, -58] });
addLabel(SERIF('Roll'), V3(0, 0, 4.6), { fontSize: '21px', offset: [18, 62] });

addLabel(SERIF('<b>P</b>'), P_WORLD, { fontSize: '23px', offset: [-2, -30] });
const labp = addLabel(SERIF('<b>p</b>'), V3(0, 0, F), { fontSize: '23px', offset: [-16, -28] });
const labgy = addLabel(SERIF('<i>y</i>'), V3(0, 0, F), { fontSize: '23px', color: '#111', offset: [0, 0] });
const labgx = addLabel(SERIF('<i>x</i>'), V3(0, 0, F), { fontSize: '23px', color: '#111', offset: [0, 0] });

// labels that ride with the rotating camera frame
const dynLabels = [
  { e: labgy, local: V3(-0.44, 0.30, F) },
  { e: labgx, local: V3(0.92, -0.46, F) }
];

/* ── interactive explanations ───────────────────────────────────────────── */
registerInteractive(planeMesh, {
  title: 'Image plane',
  tooltip: 'Image plane at focal distance f = 3',
  body: 'The image plane sits perpendicular to the optical axis at distance f, spanned by the camera frame\u2019s x and y directions (green). Rotating the camera by R moves this whole plane rigidly, so the fixed world point P projects to a different image point p.'
});
registerInteractive(PDisc, {
  title: 'World point P',
  tooltip: 'Fixed 3D world point P',
  body: 'P = (0.5, 1.75, 6.3) is fixed in the world. Its camera coordinates are Pc = R⁻¹P, and the image point is p = f·(Pc.x, Pc.y)/Pc.z in the rotated camera frame. The grey poly-line drops P onto the XZ plane and back to the Z axis so you can read its depth.'
});
registerInteractive(arcYaw, {
  title: 'Yaw θ_Y (about Y)',
  tooltip: 'Yaw: rotation about the vertical Y axis',
  body: 'Yaw swings the optical axis left/right about the vertical axis. For a fixed P the image point p slides mostly horizontally across the plane.'
});
registerInteractive(arcPitch, {
  title: 'Pitch θ_X (about X)',
  tooltip: 'Pitch: rotation about the lateral X axis',
  body: 'Pitch tips the optical axis up/down about the lateral axis, sliding the image point p vertically.'
});
registerInteractive(arcRoll, {
  title: 'Roll θ_Z (about Z)',
  tooltip: 'Roll: rotation about the optical axis Z',
  body: 'Roll spins the image plane about its own optical axis. The camera keeps looking the same way, but the green x and y axes turn, so p moves on a circle about the principal point.'
});

/* ── highlight groups ───────────────────────────────────────────────────── */
function matsOf(obj) {
  const out = [];
  obj.traverse(o => { if (o.material && o.material.color) { o.material.transparent = true; out.push(o.material); } });
  return out;
}
const axisMats = {
  y: matsOf(axY).concat(matsOf(arcYaw)),
  x: matsOf(axX).concat(matsOf(arcPitch)),
  z: matsOf(axZ).concat(matsOf(arcRoll))
};
function setHighlight(axis) {
  for (const k of ['x', 'y', 'z']) {
    const on = !axis || axis === k;
    axisMats[k].forEach(m => { m.opacity = on ? 1.0 : 0.14; });
  }
}
setHighlight(null);

/* ── state, rotation composition, projection update ─────────────────────── */
const state = { yaw: 0, pitch: 0, roll: 0, order: 'ypr' };
const _qy = new THREE.Quaternion(), _qx = new THREE.Quaternion(), _qz = new THREE.Quaternion();
const _q = new THREE.Quaternion(), _qi = new THREE.Quaternion();
const _pc = new THREE.Vector3(), _pl = new THREE.Vector3(), _tmp = new THREE.Vector3();

function composeR() {
  const r = THREE.MathUtils.degToRad;
  _qy.setFromAxisAngle(V3(0, 1, 0), r(state.yaw));
  _qx.setFromAxisAngle(V3(1, 0, 0), r(state.pitch));
  _qz.setFromAxisAngle(V3(0, 0, 1), r(state.roll));
  if (state.order === 'ypr') _q.copy(_qz).multiply(_qx).multiply(_qy);   // R = Rz Rx Ry
  else _q.copy(_qy).multiply(_qx).multiply(_qz);                          // R = Ry Rx Rz
  return _q;
}

const pStat = document.getElementById('pStat');

function applyState() {
  const q = composeR();
  camGroup.quaternion.copy(q);
  camGroup.updateMatrixWorld(true);

  _qi.copy(q).invert();
  _pc.copy(P_WORLD).applyQuaternion(_qi);       // camera coordinates of P

  if (_pc.z > 0.25) {
    _pl.set(F * _pc.x / _pc.z, F * _pc.y / _pc.z, F);
    pDisc.visible = true;
    pDisc.position.set(_pl.x, _pl.y, _pl.z + 0.08);
    setSeg(dropSeg, V3(_pl.x, _pl.y, F + 0.06), V3(_pl.x, 0, F + 0.06));

    const outside = Math.abs(_pl.x) > PW / 2 || _pl.y > PCY + PH / 2 || _pl.y < PCY - PH / 2;
    pDisc.userData.core.material.opacity = outside ? 0.35 : 1.0;
    pStat.style.color = outside ? '#b06000' : '#0a6';
    pStat.innerHTML = outside
      ? `p = (${_pl.x.toFixed(2)}, ${_pl.y.toFixed(2)}) &mdash; outside the image rectangle`
      : `p = (${_pl.x.toFixed(2)}, ${_pl.y.toFixed(2)}) on the image plane`;

    _tmp.copy(_pl); camGroup.localToWorld(_tmp);
    labp.pos.copy(_tmp);
    labp.div.innerHTML = SERIF('<b>p</b>');
  } else {
    pDisc.visible = false; dropSeg.visible = false;
    labp.div.innerHTML = '';
    pStat.style.color = '#c00';
    pStat.innerHTML = 'P is behind the camera &mdash; no image point.';
  }

  for (const dl of dynLabels) {
    _tmp.copy(dl.local); camGroup.localToWorld(_tmp); dl.e.pos.copy(_tmp);
  }
}

/* ── UI wiring ──────────────────────────────────────────────────────────── */
const sYaw = document.getElementById('sYaw'), sPitch = document.getElementById('sPitch'),
      sRoll = document.getElementById('sRoll');
const vYaw = document.getElementById('vYaw'), vPitch = document.getElementById('vPitch'),
      vRoll = document.getElementById('vRoll');
const bYPR = document.getElementById('bYPR'), bRPY = document.getElementById('bRPY');
const ordFormula = document.getElementById('ordFormula');

function syncSliders() {
  sYaw.value = state.yaw.toFixed(0); vYaw.textContent = state.yaw.toFixed(0) + '\u00B0';
  sPitch.value = state.pitch.toFixed(0); vPitch.textContent = state.pitch.toFixed(0) + '\u00B0';
  sRoll.value = state.roll.toFixed(0); vRoll.textContent = state.roll.toFixed(0) + '\u00B0';
}
function syncOrder() {
  bYPR.classList.toggle('active', state.order === 'ypr');
  bRPY.classList.toggle('active', state.order === 'rpy');
  ordFormula.innerHTML = state.order === 'ypr'
    ? 'R = R<sub>z</sub>(&theta;<sub>Z</sub>) R<sub>x</sub>(&theta;<sub>X</sub>) R<sub>y</sub>(&theta;<sub>Y</sub>)'
    : 'R = R<sub>y</sub>(&theta;<sub>Y</sub>) R<sub>x</sub>(&theta;<sub>X</sub>) R<sub>z</sub>(&theta;<sub>Z</sub>)';
}

let queue = [], seg = null, segT = 0;
function clearAnim() { queue.length = 0; seg = null; setHighlight(null); }
function enqueue(to, dur, axis) { queue.push({ to, dur: dur ?? 900, axis: axis ?? null }); }

function onSlider() {
  clearAnim();
  state.yaw = +sYaw.value; state.pitch = +sPitch.value; state.roll = +sRoll.value;
  syncSliders(); applyState();
}
sYaw.addEventListener('input', onSlider);
sPitch.addEventListener('input', onSlider);
sRoll.addEventListener('input', onSlider);

bYPR.addEventListener('click', () => { state.order = 'ypr'; syncOrder(); applyState(); });
bRPY.addEventListener('click', () => { state.order = 'rpy'; syncOrder(); applyState(); });

document.getElementById('bZero').addEventListener('click', () => {
  clearAnim(); state.yaw = state.pitch = state.roll = 0; syncSliders(); applyState();
});

document.getElementById('bAnim').addEventListener('click', () => {
  clearAnim();
  let ty = state.yaw, tp = state.pitch, tr = state.roll;
  if (Math.abs(ty) < 1 && Math.abs(tp) < 1 && Math.abs(tr) < 1) { ty = 35; tp = 25; tr = 40; }
  state.yaw = state.pitch = state.roll = 0; syncSliders(); applyState();
  enqueue({ yaw: ty }, 1300, 'y');
  enqueue({ yaw: ty }, 350, 'y');
  enqueue({ pitch: tp }, 1300, 'x');
  enqueue({ pitch: tp }, 350, 'x');
  enqueue({ roll: tr }, 1300, 'z');
  enqueue({ roll: tr }, 400, null);
});

/* ── guided demo steps ──────────────────────────────────────────────────── */
const STEPS = [
  { title: 'Canonical camera', narr: 'With all three angles zero the image plane sits square across the Z axis; the dashed ray from the origin to P pierces it at the image point p, just above the local x axis.', s: { yaw: 0, pitch: 0, roll: 0, order: 'ypr' } },
  { title: 'Yaw about Y', narr: 'Turning θ_Y about the vertical axis swivels the camera sideways; p slides horizontally across the image plane while P stays fixed in the world.', s: { yaw: 35, pitch: 0, roll: 0, order: 'ypr' } },
  { title: 'Then pitch about X', narr: 'Adding θ_X tips the already-yawed frame up; the pitch happens about the rotated X axis, so p moves diagonally, not straight down.', s: { yaw: 35, pitch: 25, roll: 0, order: 'ypr' } },
  { title: 'Then roll about Z', narr: 'θ_Z spins the plane about its own optical axis: the green x and y axes rotate and p swings around the principal point without the camera looking anywhere new.', s: { yaw: 35, pitch: 25, roll: 40, order: 'ypr' } },
  { title: 'Same angles, reversed order', narr: 'Applying roll first and yaw last with identical angle values lands the image plane in a visibly different orientation — rotation composition is not commutative.', s: { yaw: 35, pitch: 25, roll: 40, order: 'rpy' } }
];
let stepIdx = 0;
const stepTitle = document.getElementById('stepTitle'), stepNarr = document.getElementById('stepNarr');

function goToStep(i) {
  stepIdx = (i + STEPS.length) % STEPS.length;
  const st = STEPS[stepIdx];
  clearAnim();
  state.order = st.s.order; syncOrder();
  stepTitle.textContent = `${stepIdx + 1}/${STEPS.length} · ${st.title}`;
  stepNarr.textContent = st.narr;
  const axis = stepIdx === 1 ? 'y' : stepIdx === 2 ? 'x' : (stepIdx === 3 || stepIdx === 4) ? 'z' : null;
  enqueue({ yaw: st.s.yaw, pitch: st.s.pitch, roll: st.s.roll }, 1000, axis);
  enqueue({ yaw: st.s.yaw, pitch: st.s.pitch, roll: st.s.roll }, 500, null);
}
document.getElementById('bNext').addEventListener('click', () => goToStep(stepIdx + 1));
document.getElementById('bPrev').addEventListener('click', () => goToStep(stepIdx - 1));

/* ── tween loop (independent of the scaffold render loop) ───────────────── */
let _prevT = performance.now();
function updateLoop(now) {
  requestAnimationFrame(updateLoop);
  const dt = Math.min(64, now - _prevT); _prevT = now;
  if (!seg && queue.length) {
    seg = queue.shift();
    seg.from = { yaw: state.yaw, pitch: state.pitch, roll: state.roll };
    segT = 0;
    setHighlight(seg.axis);
  }
  if (seg) {
    segT += dt;
    const u = Math.min(1, segT / seg.dur);
    const e = u < 0.5 ? 2 * u * u : 1 - Math.pow(-2 * u + 2, 2) / 2;
    for (const k of ['yaw', 'pitch', 'roll']) {
      if (seg.to[k] !== undefined) state[k] = seg.from[k] + (seg.to[k] - seg.from[k]) * e;
    }
    syncSliders();
    applyState();
    if (u >= 1) seg = null;
  }
}
requestAnimationFrame(updateLoop);

/* ── initial state ──────────────────────────────────────────────────────── */
syncSliders(); syncOrder(); applyState();
stepTitle.textContent = `1/${STEPS.length} · ${STEPS[0].title}`;
stepNarr.textContent = STEPS[0].narr;
